def seed_genders(apps, schema_editor):
    Gender = apps.get_model("members", "Gender")
    Member = apps.get_model("members", "Member")
    defaults = [
        ("male", "Male"),
        ("female", "Female"),
        ("other", "Other"),
        ("unspecified", "Prefer not to say"),
    ]
    for order, (code, name) in enumerate(defaults):
        Gender.objects.using(schema_editor.connection.alias).get_or_create(
            code=code, defaults={"name": name, "sort_order": order}
        )
    for code in (
        Member.objects.using(schema_editor.connection.alias)
        .exclude(gender="")
        .values_list("gender", flat=True)
        .distinct()
    ):
        Gender.objects.using(schema_editor.connection.alias).get_or_create(
            code=code, defaults={"name": code.capitalize()}
        )
    Permission = apps.get_model("auth", "Permission")
    for permission in Permission.objects.using(schema_editor.connection.alias).filter(
        content_type__app_label="members", content_type__model="district"
    ):
        permission.name = permission.name.replace("district", "branch").replace(
            "District", "Branch"
        )
        permission.save(update_fields=["name"])


